'use strict';

const express = require('express');
const { sendError } = require('../utils/errors');

const PLAYERS_COLLECTION = 'players';
const LEADERBOARD_PREFIX = 'leaderboard_';

/**
 * Creates the Leaderboard Express router.
 * 
 * @param {object} options
 * @param {object} options.storage - Conforming storage adapter
 * @returns {import('express').Router}
 */
function createLeaderboardRouter({ storage }) {
  const router = express.Router();
  router.use(express.json());

  /**
   * Helper to get board collection name.
   */
  function getBoardCollection(board) {
    return `${LEADERBOARD_PREFIX}${board.toLowerCase().trim()}`;
  }

  /**
   * POST /:board
   * Submit or update a player's score on a given leaderboard.
   * Body: { playerId: string, score: number }
   * 
   * Best-score-only: Retains the highest score for the player on this board.
   */
  router.post('/:board', async (req, res, next) => {
    try {
      const { board } = req.params;
      const { playerId, score } = req.body || {};

      if (!board || typeof board !== 'string' || board.trim().length === 0) {
        return sendError(res, 400, 'Leaderboard name is required');
      }

      if (!playerId || typeof playerId !== 'string' || playerId.trim().length === 0) {
        return sendError(res, 400, 'playerId is required and must be a string');
      }

      if (score === undefined || typeof score !== 'number' || !Number.isFinite(score)) {
        return sendError(res, 400, 'score is required and must be a finite number');
      }

      const cleanPlayerId = playerId.trim();
      const cleanBoard = board.trim();

      // Verify that the player exists in the players store
      const player = await storage.get(PLAYERS_COLLECTION, cleanPlayerId);
      if (!player) {
        return sendError(res, 404, 'Player not found');
      }

      const collectionName = getBoardCollection(cleanBoard);
      const existingEntry = await storage.get(collectionName, cleanPlayerId);

      // Best-score-only logic: only update if no existing score or new score is higher
      if (existingEntry && existingEntry.score >= score) {
        return res.status(200).json({
          board: cleanBoard,
          playerId: cleanPlayerId,
          score: existingEntry.score,
          updatedAt: existingEntry.updatedAt,
          updated: false
        });
      }

      const entry = {
        board: cleanBoard,
        playerId: cleanPlayerId,
        playerName: player.name,
        score,
        updatedAt: new Date().toISOString()
      };

      await storage.set(collectionName, cleanPlayerId, entry);

      const statusCode = existingEntry ? 200 : 201;
      return res.status(statusCode).json({
        ...entry,
        updated: true
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * GET /:board/rank/:playerId
   * Returns a single player's rank and score on a board.
   */
  router.get('/:board/rank/:playerId', async (req, res, next) => {
    try {
      const { board, playerId } = req.params;

      if (!board || !board.trim()) {
        return sendError(res, 400, 'Leaderboard name is required');
      }
      if (!playerId || !playerId.trim()) {
        return sendError(res, 400, 'playerId is required');
      }

      const cleanBoard = board.trim();
      const cleanPlayerId = playerId.trim();
      const collectionName = getBoardCollection(cleanBoard);

      const items = await storage.list(collectionName);
      if (!items || items.length === 0) {
        return sendError(res, 404, 'Player not found on leaderboard');
      }

      // Sort descending by score; secondary sort by earliest updatedAt
      items.sort((a, b) => {
        if (b.score !== a.score) return b.score - a.score;
        return new Date(a.updatedAt) - new Date(b.updatedAt);
      });

      const playerIndex = items.findIndex(item => item.playerId === cleanPlayerId);
      if (playerIndex === -1) {
        return sendError(res, 404, 'Player not found on leaderboard');
      }

      const entry = items[playerIndex];
      return res.status(200).json({
        rank: playerIndex + 1,
        board: cleanBoard,
        playerId: entry.playerId,
        playerName: entry.playerName,
        score: entry.score,
        updatedAt: entry.updatedAt
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * GET /:board
   * Get top scores for a leaderboard with rank.
   * Query: ?limit=10 (capped at 100)
   */
  router.get('/:board', async (req, res, next) => {
    try {
      const { board } = req.params;

      if (!board || typeof board !== 'string' || board.trim().length === 0) {
        return sendError(res, 400, 'Leaderboard name is required');
      }

      let limit = 10;
      if (req.query.limit !== undefined) {
        const parsedLimit = parseInt(req.query.limit, 10);
        if (isNaN(parsedLimit) || parsedLimit <= 0) {
          return sendError(res, 400, 'Query param "limit" must be a positive integer');
        }
        limit = Math.min(parsedLimit, 100);
      }

      const cleanBoard = board.trim();
      const collectionName = getBoardCollection(cleanBoard);
      const items = await storage.list(collectionName);

      // Sort descending by score, tie-break by earliest updatedAt
      items.sort((a, b) => {
        if (b.score !== a.score) return b.score - a.score;
        return new Date(a.updatedAt) - new Date(b.updatedAt);
      });

      const topEntries = items.slice(0, limit).map((entry, index) => ({
        rank: index + 1,
        board: cleanBoard,
        playerId: entry.playerId,
        playerName: entry.playerName,
        score: entry.score,
        updatedAt: entry.updatedAt
      }));

      return res.status(200).json(topEntries);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

module.exports = {
  createLeaderboardRouter
};
